# AUTO-GENERATED by Claude Code
# Purpose: EXPERIMENT (branch exp/ghostty-terminal): the Terminal pane, the simplest
#          ghostty-web integration. GET /terminal is a page that loads ghostty-web (the Ghostty
#          terminal in the browser, from a CDN) and talks to /terminal/ws, which runs $SHELL in
#          a pseudo-terminal on this machine. The pane frames that page (ui.terminal_pane).
# Safety: the WebSocket starts a real shell, so it only takes connections from this machine
#          and from the app's own pages (allowed_origin), as ghostty-web's own demo does.
# Usage: Alt+` shows / hides the Terminal pane (as VS Code's Ctrl+`), Alt+Shift+` full screen.
# ---------------------------------------------------------------------------
from __future__ import annotations

import asyncio
import codecs
import contextlib
import fcntl
import json
import os
import pty
import signal
import struct
import termios
from pathlib import Path
from typing import TYPE_CHECKING
from urllib.parse import urlsplit

from starlette.responses import HTMLResponse

if TYPE_CHECKING:
    from starlette.websockets import WebSocket

__all__ = ["GHOSTTY_WEB", "PAGE", "allowed_origin", "page", "shell_command", "shell_socket"]

# ds::external-source: checked 2026-11-17 https://github.com/coder/ghostty-web
#   (README, demo/index.html) taken from it: `init()` then `new Terminal({...})`, `open(el)`,
#   `onData`, `write`, `onResize`, FitAddon (`fit()`, `observeResize()`); raw text both ways,
#   a JSON {"type":"resize"} message; the npm build embeds its WASM as base64, so this one
#   file is all the page loads
GHOSTTY_WEB = "https://cdn.jsdelivr.net/npm/ghostty-web@0.4.0/dist/ghostty-web.js"
LOCAL_HOSTS = {"localhost", "127.0.0.1", "::1"}
READ_SIZE = 65536


def shell_command() -> str:
    """The shell the Terminal runs: $SHELL, else /bin/bash."""
    return os.environ.get("SHELL", "/bin/bash")


# The page the Terminal pane frames. Everforest, as the app (assets/app.css).
PAGE = """<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>Terminal</title>
<style>
  html, body { margin: 0; height: 100%; background: #2d353b; overflow: hidden; }
  #term { position: absolute; inset: 4px 0 0 6px; }
  #note { position: absolute; bottom: 6px; right: 10px; font: 12px sans-serif; color: #e67e80; }
</style>
</head>
<body>
<div id="term"></div>
<div id="note"></div>
<script type="module">
  import { init, Terminal, FitAddon } from "GHOSTTY_WEB";
  const note = document.getElementById("note");
  await init();
  // Sharp text at the size your own terminal uses (FONT_PT points, at SCREEN_SCALE). The app's
  // browser zoom (eg 110%) would make each character cell a fraction of a screen pixel (ghostty
  // rounds cells to whole CSS pixels), smearing the text. So the box undoes the zoom with CSS
  // zoom, and ghostty draws at the monitor's own pixel ratio: every cell is whole screen pixels.
  const browserZoom = window.devicePixelRatio / SCREEN_SCALE;
  document.getElementById("term").style.zoom = String(1 / browserZoom);
  // ghostty-web 0.4.0's Terminal doesn't pass a devicePixelRatio option on to its renderer,
  // which reads the window's: this page (only) reports the monitor's own ratio
  Object.defineProperty(window, "devicePixelRatio", { get: () => SCREEN_SCALE });
  const term = new Terminal({
    fontSize: Math.round(FONT_PT * 96 / 72),
    fontFamily: '"JetBrainsMono Nerd Font", "JetBrains Mono", monospace',
    cursorBlink: true,
    scrollback: 10000,
    theme: { background: "#2d353b", foreground: "#d3c6aa", cursor: "#d3c6aa" },
  });
  const fit = new FitAddon();
  term.loadAddon(fit);
  term.open(document.getElementById("term"));
  fit.fit();
  fit.observeResize();
  const ws = new WebSocket(`${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/terminal/ws?cols=${term.cols}&rows=${term.rows}`);
  ws.onmessage = (event) => term.write(event.data);
  ws.onclose = () => { note.textContent = "shell ended: close this or open a new Terminal"; };
  term.onData((data) => ws.readyState === 1 && ws.send(data));
  term.onResize(({ cols, rows }) => ws.readyState === 1 && ws.send(JSON.stringify({ type: "resize", cols, rows })));
  term.focus();
  window.addEventListener("focus", () => term.focus());  // the app focuses this frame on Alt+`
  // The pane's own keys (Alt+` hide, Alt+Shift+` full screen) work from inside it too: the
  // shell would get them otherwise. Sent to the app, which runs them (assets/panes.js).
  document.addEventListener("keydown", (event) => {
    if (!event.altKey || event.ctrlKey || event.metaKey || event.code !== "Backquote") return;
    event.preventDefault();
    event.stopImmediatePropagation();
    parent.postMessage({ type: "delulu-press", keys: event.shiftKey ? "Alt+Shift+`" : "Alt+`" }, "*");
  }, true);
</script>
</body>
</html>
""".replace("GHOSTTY_WEB", GHOSTTY_WEB)

# where the font size of the terminal you use outside the app is read, first found wins:
# (config file under ~/.config, the line's key)
TERMINAL_CONFIGS = (("ghostty/config", "font-size"), ("kitty/kitty.conf", "font_size"))
DEFAULT_FONT_PT = 9.0  # Omarchy's own terminals' size


def terminal_font_pt() -> float:
    """Your own terminal's font size, in points (ghostty's, else kitty's, else Omarchy's 9)."""
    for name, key in TERMINAL_CONFIGS:
        path = Path.home() / ".config" / name
        if not path.is_file():
            continue
        for line in path.read_text(errors="replace").splitlines():
            found, _, value = line.replace("=", " ").strip().partition(" ")
            if found == key:
                with contextlib.suppress(ValueError):
                    return float(value.strip())
    return DEFAULT_FONT_PT


async def screen_scale() -> float:
    """The focused monitor's scale (Hyprland), so a scaled display gets the same size; 1 if
    it can't be read (not Hyprland, or hyprctl is slow).
    """
    with contextlib.suppress(Exception):
        proc = await asyncio.create_subprocess_exec(
            "hyprctl", "monitors", "-j", stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
        )
        out, _ = await asyncio.wait_for(proc.communicate(), 1)
        monitors = json.loads(out)
        return float(next((m for m in monitors if m.get("focused")), monitors[0])["scale"])
    return 1.0


async def page(_request: object) -> HTMLResponse:
    """GET /terminal: the page the Terminal pane frames, its text sized as your terminal."""
    sizes = {"FONT_PT": str(terminal_font_pt()), "SCREEN_SCALE": str(await screen_scale())}
    html = PAGE
    for name, value in sizes.items():
        html = html.replace(name, value)
    return HTMLResponse(html)


def allowed_origin(origin: str, client_host: str) -> bool:
    """Whether a WebSocket may start a shell: it comes from this machine, from a page on this
    machine (the app's, eg http://localhost:8000). A page on any other site is refused.
    """
    return client_host in LOCAL_HOSTS and urlsplit(origin).hostname in LOCAL_HOSTS


def _set_size(fd: int, cols: int, rows: int) -> None:
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", max(rows, 1), max(cols, 1), 0, 0))


async def shell_socket(ws: WebSocket) -> None:
    """/terminal/ws: one shell per connection, in a pseudo-terminal. Text from the page is
    typed into it (a {"type": "resize"} message resizes it); what it prints goes back as text.
    The shell is hung up when the page goes (the widget closed or re-mounted).
    """
    client = ws.client.host if ws.client else ""
    if not allowed_origin(ws.headers.get("origin", ""), client):
        await ws.close(code=1008)  # policy violation: not from this machine's pages
        return
    await ws.accept()
    # no fork of this (threaded) server running Python in the child: util-linux's `setsid
    # --ctty` gives the shell a session of its own with the pty as its terminal
    fd, tty = pty.openpty()
    _set_size(fd, int(ws.query_params.get("cols", 80)), int(ws.query_params.get("rows", 24)))
    shell = shell_command()
    # the user's own login shell, by design; setsid is util-linux's, from PATH
    proc = await asyncio.create_subprocess_exec(
        "setsid",
        "--ctty",
        shell,
        "-l",
        stdin=tty,
        stdout=tty,
        stderr=tty,
        env={**os.environ, "TERM": "xterm-256color"},
        cwd=Path.home(),
    )
    os.close(tty)  # the shell holds it now
    loop = asyncio.get_running_loop()
    output: asyncio.Queue[bytes] = asyncio.Queue()

    def readable() -> None:
        try:
            output.put_nowait(os.read(fd, READ_SIZE))
        except OSError:  # the shell exited: the pty is closed
            loop.remove_reader(fd)
            output.put_nowait(b"")

    loop.add_reader(fd, readable)

    async def pump_out() -> None:
        decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
        while chunk := await output.get():
            await ws.send_text(decoder.decode(chunk))
        await ws.close()

    sender = asyncio.create_task(pump_out())
    try:
        while True:
            message = await ws.receive_text()
            if message.startswith('{"type":"resize"'):
                size = json.loads(message)
                _set_size(fd, int(size["cols"]), int(size["rows"]))
            else:
                os.write(fd, message.encode())
    except Exception:  # noqa: BLE001, S110  # the page went away (a disconnect): hang up below
        pass
    finally:
        sender.cancel()
        loop.remove_reader(fd)
        with contextlib.suppress(ProcessLookupError):
            os.killpg(proc.pid, signal.SIGHUP)  # the shell's session: it and what it started
        with contextlib.suppress(OSError):
            os.close(fd)
        await proc.wait()
